// animations
class Puppeteer {
    constructor(points, personSpawnID, targetRoom, footing, targetID) {
        this.points = points//points is a list of x,y objects like {"x":10,"y":12}, they will be in an array like [point1, point2, point3] etc.
        this.targetRoom = targetRoom//Target room is where the new character will spawn 
        this.personSpawnID = personSpawnID //this is the ID of who will spawn in the room (at the footing)
        this.footing = footing //this is an  x,y object, just one, not a list, like point =  {"x":10,"y":12}, and it's where the npc will spawn
        this.targetID = targetID - 1 //this is the ID of who will be moved in the room to a new position, and will tag their people object to animate a walk animation(which exist)
        this.delay = 100

        //animation variables, these control the puppeting 
        this.count = 0 //what "frame" of the interpolation between the points selected
        this.pointer1 = 0; //this is the starting point in the array for where to interopolate from
        this.pointer2 = 1 // this is the number that is the index of the point to interpolate to 
        this.distances = [0] //arraay this holds the distances in pixels from A to B as they traverse
        this.lengths = [0] //the lengths in frames of how long they will be walking from a to b
        this.link = new LineOP(this.points[0], this.points[1]) //dummy line object for geometry
        let sum = 0

        for (let t = 1; t < this.points.length; t++) { //loop for calculating the distances and lengths
            this.link.target = this.points[t] //this sets the line geometry to measure from the point at index t
            this.link.object = this.points[t - 1]//this sets the line geometry to measure to the point at index t-1,,this with the array starting loop at 1 means it won't overflow, regardless of the points, as long as there are two or more
            let h = this.link.hypotenuse() //h is the hypotenuse of the line that connects the points in question, and makes for a measure of their euclidian distance
            this.distances.push(h) //then we store that distance
            this.lengths.push(Math.ceil(h / 6))  //and also store the length in frames they will be animated for
            sum += Math.ceil(h / 6)
        }

        this.lengthsum = sum

        this.active = 1// sets up to run automatically on formation of trigger
        PuppeteerArray.push(this)
    }
    interpolate(point1, point2, time, length) {
        let x = point1.x + ((point2.x - point1.x) * (time / length)) //averaging from x to x on a time slider
        let y = point1.y + ((point2.y - point1.y) * (time / length))//averaging from y to y on a time slider
        return { "x": x, "y": y }
    }
    play() { //this will be on all triggerd puppet objects, in a loop of their array, in main probably at the top, and there will need to be a cleanup function


        if (this.active == 1) {

            keysPressed['p'] = false
            backManager.lockflag = 1
            if (this.delay > 0) {
                this.delay--
                return
            }



            this.secretslide = -1
            let wet = 0
            //lookup people data and convert them to a class variable called target person
            for (let g = 0; g < backManager.people.length; g++) {
                for (let t = 0; t < backManager.people[g].length; t++) {
                    if (backManager.people[g][t].form == this.targetID) {
                        this.targetPerson = t
                        this.secretslide = g
                        wet = 1
                        break
                    }
                }
            }
            if (wet == 0) { this.active = 0; return }

            if (!this.points[this.pointer2]) { this.active = 0; return }

            let interpoint = this.interpolate(this.points[this.pointer1], this.points[this.pointer2], this.count, this.lengths[this.pointer2]) //call for the creation of a point that is where the npc should be drawn
            // console.log(interpoint)
            if (backManager.people[this.secretslide][this.targetPerson]) {
                backManager.people[this.secretslide][this.targetPerson].body.x = interpoint.x
                backManager.people[this.secretslide][this.targetPerson].body.y = interpoint.y
                backManager.people[this.secretslide][this.targetPerson].body.animated = 1
                backManager.people[this.secretslide][this.targetPerson].walking = 1
                backManager.people[this.secretslide][this.targetPerson].puppet = 1
                backManager.people[this.secretslide][this.targetPerson].passedWalk = Math.sign(interpoint.x - this.interpolate(this.points[this.pointer1], this.points[this.pointer2], this.count - 1, this.lengths[this.pointer2]).x)
                if (backManager.people[this.secretslide][this.targetPerson].passedWalk == 0) {
                    backManager.people[this.secretslide][this.targetPerson].passedWalk = 1
                }

                this.count++
                if (this.count > this.lengths[this.pointer2]) {
                    this.count = 0
                    this.pointer1++ //increment to the next point
                    this.pointer2++ //increment to the next point
                    if (this.pointer2 > this.points.length - 1) { //

                        console.log(this, backManager.people[this.secretslide][this.targetPerson])
                        backManager.people[this.secretslide][this.targetPerson].kill = 1  //code to remove target person from the array of people

                        let newDude = new Person(this.personSpawnID - 1, this.footing.x, this.footing.y)   //code to add people to other room 
                        if (this.targetRoom == -1) {

                        } else {
                            if (backManager.people[this.targetRoom]) {
                                backManager.people[this.targetRoom].push(newDude)
                            }


                        }
                        this.cleanup()
                    }
                }
            }


        }

    }
    cleanup() {
        this.active = 0
    }

}









