    check(point){
        let mallow = -1
        let dpoint = new Point(Math.round(point.x), Math.round(point.y))
        if(walk_box[backManager.slide].pixmap[walk_box[backManager.slide].self_tile_check(walk_box[backManager.slide].width, walk_box[backManager.slide].height, dpoint.x, dpoint.y)+2] > colorConstcy){
            return true
        }else{
            return false
        }
    }

    path_reset(){
        this.path = [new Tile_box(this.x, this.y, walk_box[backManager.slide])]
    }

    demandAudio(charID, audioName, delay = 0) {  //deko.demandAudio(1,"thanks"); -> plays the sound, thats it.

        for (let t = 0; t < storedAudioTriggers.length; t++) {
            if (storedAudioTriggers[t].characterID == charID) {
                for (let k = 0; k < storedAudioTriggers[t].stuff.length; k++) {
                    if (storedAudioTriggers[t].stuff[k][audioName] > 0) {
                        if (bs.length > 0) {

                        } else {
                            if (!(this.playfile.state == 'running')) {
                                this.playfile = new Audio()
                                this.playfile.src = storedAudioTriggers[t].stuff[k].file
                                this.playfile.play()
                            }

                        }
                        return
                    }

                }

            }
        }

    }



    demandVideo(putin) {  //"Trigger: 'deko.demandVideo(`Video00.mp4`)'"



        globalvideo = document.createElement('video');
        globalvideo.src = putin;  // Replace with your video file path
        globalvideo.autoplay = false;
        globalvideo.loop = false;
        playable = 0

        if (bs.length > 0) {

        } else {

            globalvideo.addEventListener('loadeddata', () => {
                backManager.lock = 1
                backManager.locktimer = ((globalvideo.duration * 1000) / 17)
                console.log('s')
                playable = 1
            });
        }
    }

