function drawSprite(ctx, spriteSheet, sx, sy, sWidth, sHeight, dx, dy, dWidth, dHeight, flipHorizontally) {
    ctx.save();

    if (flipHorizontally) {
        ctx.scale(-1, 1);
        ctx.translate(-dx - ((deko.x) + (64 * deko.scale)), 0);
    }
    ctx.drawImage(spriteSheet, sx, sy, sWidth, sHeight, dx, dy, dWidth, dHeight);

    ctx.restore();
}
function drawSpriteBul(ctx, spriteSheet, sx, sy, sWidth, sHeight, dx, dy, dWidth, dHeight, flipHorizontally, bul) {
    ctx.save();

    if (flipHorizontally && deko.dir == -1) {
        ctx.scale(-1, 1);
        ctx.translate((-dx - ((backManager.offset.x + (backManager.offset.x - deko.x)) + (64 * deko.scale))) - bul, 0);
    }
    ctx.drawImage(spriteSheet, sx, sy, sWidth, sHeight, dx + (backManager.offset.x - deko.x), dy, dWidth, dHeight);

    ctx.restore();
}
function drawSpriteMan(ctx, spriteSheet, sx, sy, sWidth, sHeight, dx, dy, dWidth, dHeight, flipHorizontally, guy) {
    ctx.save();

    if (flipHorizontally) {
        ctx.scale(-1, 1);
        ctx.translate(-dx - ((guy.body.x) + (64 * guy.scale)), 0);
    }
    ctx.drawImage(spriteSheet, sx, sy, sWidth, sHeight, dx, dy, dWidth, dHeight);

    ctx.restore();
}
function drawSpriteFace(ctx, spriteSheet, sx, sy, sWidth, sHeight, dx, dy, dWidth, dHeight, flipHorizontally, guy) {
    ctx.save();

    if (flipHorizontally) {
        ctx.scale(-1, 1);

        let transform = ctx.getTransform();
        if (transform.e != 0) {

            ctx.translate(-dx - ((1650 - transform.e) + (64 * 4)), 0);
        } else {


            ctx.translate(-dx - ((1920)), 0);
        }
    }
    ctx.drawImage(spriteSheet, sx, sy, sWidth, sHeight, dx, dy, dWidth, dHeight);

    ctx.restore();
}
function drawSpriteFaceThought(ctx, spriteSheet, sx, sy, sWidth, sHeight, dx, dy, dWidth, dHeight, flipHorizontally, guy) {
    ctx.save();

    if (flipHorizontally) {
        ctx.scale(-1, 1);
    }
    ctx.drawImage(spriteSheet, sx, sy, sWidth, sHeight, -dx, dy, dWidth, dHeight);

    ctx.restore();
}

