let dust = []
for (let t = 0; t < 169; t++) {
    let img = new Image()
    if (t < 10) {
        img.src = `bg00${t}blue.png`
    } else if (t >= 10 && t < 100) {

        img.src = `bg0${t}blue.png`
    } else {

        img.src = `bg${t}blue.png`
    }
    dust.push(img)
}
function getPixelIndex(canvasWidth, canvasHeight, x, y) {
    x = Math.max(0, Math.min(canvasWidth - 1, Math.round(x)));
    y = Math.max(0, Math.min(canvasHeight - 1, Math.round(y)));
    const index = (y * canvasWidth + x) * 4;
    if (x <= 0 || y <= 0) {
        return 0
    }
    return index;
}

function getPixelIndex_path(canvasWidth, canvasHeight, x, y) {
    x = Math.max(0, Math.min(canvasWidth - 1, Math.round(x)));
    y = Math.max(0, Math.min(canvasHeight - 1, Math.round(y)));
    const index = (y * canvasWidth + x) * 4;
    if (x <= 0 || y <= 0) {
        return 0
    }
    return index;
}



