let pages = []
for (let t = 0; t < 31; t++) {
    //console.log("f")
    let img = new Image()
    if (t < 10) {
        //console.log("f")
        img.src = `book_00${t}.png`
    } else if (t >= 10 && t < 100) {

        img.src = `book_0${t}.png`
    } else {

        img.src = `book_${t}.png`
    }
    pages.push(img)
}

