// ";dekoshift = new Fade(x,y);"


class Fade {
    constructor(x, y) {
        this.alpha = 0
        this.angle = 0
        this.x = x
        this.y = y
        this.time = 240
    }
    draw() {
        this.time--
        if (this.time < 120) {
            return
        }
        backManager.spacebarlock = 1
        backManager.locktimer = 2
        this.angle += (1 / (60))
        this.alpha = 1 - Math.abs((60 - (240 - this.time)) / 60)
        if (this.time == 180) {
            backManager.offset.x = this.x
            backManager.offset.y = this.y
        }
        realcanvas_context.globalAlpha = this.alpha
        realcanvas_context.fillStyle = "black"
        realcanvas_context.fillRect(-1000, -1000, realcanvas.width * 10, realcanvas.height * 10)
        realcanvas_context.globalAlpha = 1

    }
}


