class Rejecto {
    constructor(door, guy) {
        rejections[door].guys.push(guy)
    }
}
class Ejecto {
    constructor(door, guy) {
        if (rejections[door].guys.includes(guy)) {
            rejections[door].guys.splice(rejections[door].guys.indexOf(guy), 1)
        }
    }
}




