class Front {
    constructor(img, y, slide) {
        this.img = new Image()
        this.img.src = img
        this.y = y
        this.slide = slide
    }
    draw() {

        let r = dust[backManager.slide].height / 720

        let adjustw = backManager.slides[backManager.slide].width / (r * 1280)
        let adjusth = backManager.slides[backManager.slide].height / (r * 720)
        let ratio = dust[backManager.slide].height / 1080
        let ratiow = dust[backManager.slide].width / 1920
        canvas_context.drawImage(this.img, 0, 0, backManager.slides[backManager.slide].width, backManager.slides[backManager.slide].height, 0, 0, (dust[backManager.slide].width / ratiow) * adjustw, (dust[backManager.slide].height / ratio) * 1)

    }
}

