// let animatedList = [210]


class Item {
    constructor(id, room, x, y, scale, characteristic, internal, secretmode, internalMode, trigger) {
        this.id = id
        this.yoffset = 0
        this.select = (namelessArray.includes(this.id) ? namelessArray.indexOf(this.id) : 0) //hard coded... boy's dream ollie //relative to the commented index aray above
        // //console.log(this.select, this.id, namelessArray)
        this.room = room
        this.internal = internal
        this.sacked = -1
        this.y = y
        this.x = x
        this.scale = scale
        this.owned = 0
        this.secretmode = secretmode
        this.internalMode = internalMode
        this.characteristic = characteristic
        this.menud = 0
        this.name = "item"
        this.trigger = trigger
        this.delay = 0
        if (this.id < backupNames.length) {
            this.name = backupNames[this.id]
        }

        this.frame = 0





        //console.log(this.name, itemNamePairs[backupNames[this.id]].words,itemNamePairs)
        this.words = itemNamePairs[backupNames[this.id]]
    }
    bagDraw(p1, p2, g) {
        let accessed = false
        if (this.secretmode) {

            this.characteristic = this.secretmode //?
        }
        // console.log(this)
        let transform = canvas_context.getTransform();
        this.sacked -= deko.invoffset
        if ((this.sacked <= -1 || (this.sacked) > 14)) {
            delete this.menu

        } else {
            canvas_context.fillStyle = "#FFFFFF44"
            canvas_context.strokeStyle = "#000000"
            canvas_context.lineWidth = "4"


            let x = (200 + ((this.sacked % 5) * 256)) - transform.e
            let y = 200 + (Math.floor(this.sacked / 5) * 256)
            canvas_context.fillRect(x, y, 256, 256)
            this.x = x + 16
            this.y = y + 256
            if (g == this.sacked) {
                canvas_context.lineWidth = "6"
                canvas_context.strokeStyle = "#FFFFFF"
                if (keysPressed['e']) {   //assumes no stacking
                    keysPressed['e'] = false
                    // if(this.menud == 0){
                    this.menu = new MenuItem(this.secretmode, this) //this is circular, do not save this !!!
                    // } 
                    this.menu.open = 1
                    this.menuflag = 1
                    this.menud = 1
                    accessed = true
                }
                if (keysPressed["Escape"]) {
                    if (this.menu) {
                        this.menu.open = 0
                        delete this.menu //this should prevent menu saving
                        deko.superCombine = 0
                        deko.sel1 = -1
                        deko.sel2 = -1
                        deko.comboinventory.sel = -1
                    }
                    keysPressed["Escape"] = false
                }
                if (this.menu) {
                    if (this.menu.open == 1) {
                        // this.menu.open = 1
                        this.menu.draw()
                    }
                }
            } else if (p1 == this.sacked) {
                canvas_context.strokeStyle = "#888800"

            } else if (p2 == this.sacked) {
                canvas_context.strokeStyle = "#008888"
            } else {
                if (this.menu) {
                    this.menu.open = 0
                }
            }
            canvas_context.strokeRect(x, y, 256, 256)
            canvas_context.drawImage(itemSprites[this.id], 0, 0, itemSprites[this.id].width, itemSprites[this.id].height, x, y, 256, 256) //this would change the bubble

        }
        this.sacked += deko.invoffset
        if (accessed) {
            return true
        }
        return false
    }
    draw(internum = -1) {

        if (internum == -1) {
            internum = itemList.indexOf(this)
        }
        let accessed = false
        if (this.room != backManager.slide) {
            return
        }
        if (this.delay > 0) {
            this.delay--
            return
        }
        let dot = new Circle(this.x, this.y + ItemInteractionScale, ItemInteractionScale, "#AAAA0040")
        if (this.owned == 0) {

            let x = this.x
            let y = this.y


            // if(animatedList.includes(this.id)){
            this.frame++
            canvas_context.drawImage(itemSprites[this.id], ((itemSprites[this.id].height) * this.frame) % (itemSprites[this.id].width), 0, itemSprites[this.id].height, itemSprites[this.id].height, x - ((256 * this.scale) / 2), y - ((256 * this.scale) / 2), 256 * this.scale, 256 * this.scale) //this would change the bubble
            // }else{
            //     canvas_context.drawImage(itemSprites[this.id], 0,0, itemSprites[this.id].width, itemSprites[this.id].height, x-((256*this.scale)/2), y-((256*this.scale)/2), 256*this.scale,256*this.scale) //this would change the bubble
            // }





            let n = new Point(this.x, this.y + ItemInteractionScale)  //ItemInteractionScale
            let link = new LineOP(n, backManager.offset)
            // console.log(internum ,itemList.indexOf(this))
            if (link.hypotenuse() < ItemInteractionScale && (!hiddenTips.includes(this)) && internum == itemList.indexOf(this)) {

                if (deko.indicator.text == "C/T" || deko.indicator.text == "C/T/E") {
                    deko.indicator = new Indicator("C/T/E")
                } else if (deko.indicator.text == "C" || deko.indicator.text == "C/E") {
                    deko.indicator = new Indicator("C/E")
                } else {
                    deko.indicator = new Indicator("E")
                }
                if (keysPressed['e'] && deko.invDraw != 1) {
                    keysPressed['e'] = false
                    if (this.menud == 0) {
                        this.menu = new MenuItem(this.characteristic, this) //this is circular, do not save this !!!
                    }
                    this.menu.open = 1
                    this.menuflag = 1
                    this.menud = 1
                    accessed = true
                }
            }
            if (keysPressed['Escape']) {
                if (this.menud == 0) {
                    this.menu = new MenuItem(this.characteristic, this) //this is circular, do not save this !!!
                }

                if (this.menu.open != 0) {
                    keysPressed['Escape'] = false
                }

                this.menu.open = 0
                this.menuflag = 0
                this.menud = 1
            }

            // if(keysPressed['p']){
            //     dot.draw()
            // }
        }
        if (accessed) {
            return true
        }
        return false
    }
}

