class Tile_box {
    constructor(t,k, p){
        this.t = t
        this.k = k
        this.neighbors = []
        this.p = p
        this.find_n()
    }
    find_n(){
        for(let t = -1;t<1;t++){
            for(let k = -1;k<1;k++){
                let index = this.p.self_tile_check(this.p.width, this.p.height, this.t+t, this.k+k)
                if(this.p.pixmap.data[index+2] > colorConstcy){
                    this.neighbors.push(this.p.grid[this.t+t][this.k+k])
                }
            }
        }
    }
        find_path_to(target){
        
        if (!target || target === this) {
            deko.path_reset();
            return;
        }

        const start = this;
        const openSet = [];
        const cameFrom = new Map();
        const gScore = new Map();
        const fScore = new Map();

        const getKey = (node) => `${node.t},${node.k}`;

        // === TOGGLE HERE ===

        // Initialize
        openSet.push(start);
        gScore.set(getKey(start), 0);
        fScore.set(getKey(start), heuristic(start, target, useDiagonal));

        while (openSet.length > 0) {
            // Sort by lowest fScore
            openSet.sort((a, b) => 
                (fScore.get(getKey(a)) || Infinity) - (fScore.get(getKey(b)) || Infinity)
            );

            const current = openSet.shift();

            if (current === target) {
                deko.path_reset();
                deko.path = reconstructPath(cameFrom, current);
                return;
            }

            for (let neighbor of current.neighbors) {
                // Better cost for diagonal moves
                const dx = Math.abs(current.t - neighbor.t);
                const dy = Math.abs(current.k - neighbor.k);
                const cost = (dx + dy === 2) ? Math.SQRT2 : 1;   // diagonal = √2, straight = 1

                const tentativeGScore = (gScore.get(getKey(current)) || Infinity) + cost;

                const neighborKey = getKey(neighbor);

                if (tentativeGScore < (gScore.get(neighborKey) || Infinity)) {
                    cameFrom.set(neighborKey, current);
                    gScore.set(neighborKey, tentativeGScore);
                    fScore.set(neighborKey, tentativeGScore + heuristic(neighbor, target, useDiagonal));

                    if (!openSet.some(n => n === neighbor)) {
                        openSet.push(neighbor);
                    }
                }
            }
        }

        // No path found
        deko.path_reset();
    }
}
// Heuristic with toggle
function heuristic(a, b, useDiagonal = true) {
    if (!useDiagonal) {
        // Manhattan (original simple version)
        return Math.abs(a.t - b.t) + Math.abs(a.k - b.k);
    } else {
        // Euclidean (better when diagonal movement is allowed)
        return Math.hypot(a.t - b.t, a.k - b.k);
    }
}

// Reconstruct path
function reconstructPath(cameFrom, current) {
    const path = [current];
    let node = current;
    const getKey = (n) => `${n.t},${n.k}`;

    while (cameFrom.has(getKey(node))) {
        node = cameFrom.get(getKey(node));
        path.unshift(node);
    }
    return path;
}




class BG_map {
    constructor(img, i){
        this.grid = []
        this.strip = []

        this.index_sto = -1
        this.pixmap = {}
        
        this.i = i

        this.width = dust[this.i].width * 2
        this.height = dust[this.i].height * 2

        this.assemble()

        for(let t = 0;t<img.width;t++){
            this.strip = []
            for(let k = 0;k<img.height;k++){
                let box = new Tile_box(t,k, this)
                this.strip.push(box)
            }
            this.grid.push(this.strip)
        }



    }
    assemble(img){

            let r = dust[this.i].height / 720
            let adjustw = backManager.slides[this.i].width / (r * 1280)
            let adjusth = backManager.slides[this.i].height / (r * 720)
            ratio = dust[this.i].height / 1080
            let ratiow = dust[this.i].width / 1920
            backManager.canvas.width = this.width
            backManager.canvas.height = this.height
            backManager.ctx.ImageSmoothingEnabled = false
            backManager.ctx.drawImage(dust[this.slide], 0, 0, dust[this.i].width, dust[this.i].height, 0, 0, (dust[this.i].width / ratiow) * adjustw, (dust[this.i].height / ratio) * 1)
            this.pixmap = this.ctx.getImageData(0, 0, 10000, 10000)

            

    }
    self_tile_check(canvasWidth, canvasHeight, x, y){
        this.index_sto = getPixelIndex_path(canvasWidth, canvasHeight, x, y)
        return this.index_sto
    }
}



 







