function gradOut(mus, muz) {
    let buzz = {}
    buzz.outtopic = mus
    buzz.ontopic = muz
    buzz.length = 60
    if (grades.length > 0) {
        grades[grades.length - 1].outtopic.volume = volumescaler * 0
        grades[grades.length - 1].outtopic.pause()
        grades[grades.length - 1].ontopic.volume = volumescaler * .25
    }
    grades.push(buzz)
}



