let outicoords = [new Point(2400, 1108), new Point(1404, 1556), new Point(669, 1513), new Point(1432, 1362), new Point(1040, 1542), new Point(1464, 1627)]
class Telemenu {
    constructor() {
        this.dummys = [...imagteleDummy]
        this.images = [...imagtele]
        this.select = 0
        this.coords = [...outicoords]
        this.slides = [3, 30, 98, 131, 159, 160]
        this.active = -1
    }
    draw() {
        if (this.active == 1) {
            let transform = canvas_context.getTransform();
            this.buttons = []
            for (let t = 0; t < 3; t++) {
                let rect = new Rectangle(200 + (550 * t) - transform.e, 200, 500, 300, "red")
                this.buttons.push(rect)
            }
            for (let t = 0; t < 3; t++) {
                let rect = new Rectangle(200 + (550 * t) - transform.e, 600, 500, 300, "blue")
                this.buttons.push(rect)
            }


            for (let t = 0; t < this.buttons.length; t++) {

                if (deko.roomsFirstEntry[this.slides[t]] == 1) {
                    if (this.select == t) {
                        let rect = new Rectangle(this.buttons[t].x - 10, this.buttons[t].y - 10, this.buttons[t].width + 20, this.buttons[t].height + 20, "black")
                        rect.draw()
                    }
                    canvas_context.drawImage(this.images[t], 0, 0, this.images[t].width, this.images[t].height, this.buttons[t].x, this.buttons[t].y, this.buttons[t].width, this.buttons[t].height)
                } else {
                    if (this.select == t) {
                        let rect = new Rectangle(this.buttons[t].x - 10, this.buttons[t].y - 10, this.buttons[t].width + 20, this.buttons[t].height + 20, "black")
                        rect.draw()
                    }
                    canvas_context.drawImage(this.dummys[t], 0, 0, this.dummys[t].width, this.dummys[t].height, this.buttons[t].x, this.buttons[t].y, this.buttons[t].width, this.buttons[t].height)

                }
            }
            if (throttleStickToScrollRate(keysPressed['a'], globalThrottle)) {
                keysPressed['a'] = false
                this.select--
                if (this.select < 0) {
                    this.select = 5
                }

            }
            if (keysPressed['Escape']) {
                if (this.active != -1) {
                    keysPressed['Escape'] = false
                    this.active = -1
                }
            }
            if (throttleStickToScrollRate(keysPressed['d'], globalThrottle)) {
                keysPressed['d'] = false
                this.select++
                this.select %= this.slides.length
            }
            if (throttleStickToScrollRate(keysPressed['s'], globalThrottle)) {
                keysPressed['s'] = false
                this.select += 3
                this.select %= this.slides.length
            }
            if (throttleStickToScrollRate(keysPressed['w'], globalThrottle)) {
                keysPressed['w'] = false
                this.select -= 3
                if (this.select < 0) {
                    this.select = 6 + this.select
                }
            }






            if (keysPressed[' ']) {

                if (deko.roomsFirstEntry[this.slides[this.select]] == 1) {


                    let ratioExplicit = dust[this.slides[this.select]].height / 1080
                    backManager.music[backManager.slide].pause()
                    backManager.offset.x = this.coords[this.select].x / ratioExplicit
                    backManager.offset.y = this.coords[this.select].y / ratioExplicit
                    gradOut(backManager.music[backManager.slide], backManager.music[this.slides[this.select]])
                    backManager.slide = this.slides[this.select]
                    if (deko.roomsFirstEntry[backManager.slide] == 0 && backManager.slide != 131) {
                        deko.roomsFirstEntry[backManager.slide] = 1
                        let roomtrigggers = ''
                        for (let t = 0; t < roomListOfTriggers.length; t++) {
                            if (backManager.slide == roomListOfTriggers[t].room) {
                                roomtrigggers += ";" + roomListOfTriggers[t].trigger + ";"
                            }
                        }
                        eval(roomtrigggers)
                        playedTriggers.push(roomtrigggers)
                    }
                    backManager.music[backManager.slide].play()
                    backManager.music[backManager.slide].volume = volumescaler * .25
                    backManager.hot = 1
                    this.active = -1
                }

            }
        }
    }
    check(point) {
        if (this.active == 1) {

            this.buttons = []
            for (let t = 0; t < 3; t++) {
                let rect = new Rectangle(200 + (550 * t) - 0, 200, 500, 300, "red")
                this.buttons.push(rect)
            }
            for (let t = 0; t < 3; t++) {
                let rect = new Rectangle(200 + (550 * t) - 0, 600, 500, 300, "blue")
                this.buttons.push(rect)
            }


            for (let t = 0; t < this.buttons.length; t++) {
                if (deko.roomsFirstEntry[this.slides[t]] == 1) {
                    if (this.buttons[t].isPointInside(point)) {
                        let ratioExplicit = dust[this.slides[t]].height / 1080
                        backManager.music[backManager.slide].pause()
                        backManager.offset.x = this.coords[t].x / ratioExplicit
                        backManager.offset.y = this.coords[t].y / ratioExplicit
                        backManager.slide = this.slides[t]
                        if (deko.roomsFirstEntry[backManager.slide] == 0 && backManager.slide != 131) {
                            deko.roomsFirstEntry[backManager.slide] = 1
                            let roomtrigggers = ''
                            for (let t = 0; t < roomListOfTriggers.length; t++) {
                                if (backManager.slide == roomListOfTriggers[t].room) {
                                    roomtrigggers += ";" + roomListOfTriggers[t].trigger + ";"
                                }
                            }
                            eval(roomtrigggers)
                            playedTriggers.push(roomtrigggers)
                        }
                        backManager.music[backManager.slide].play()
                        backManager.music[backManager.slide].volume = volumescaler * .25
                        backManager.hot = 1
                        this.active = -1
                        break
                    }
                }
            }
        }
    }
}
