let zcanvas = document.createElement('canvas');
zcanvas.width = 256;
zcanvas.height = 256;
zcanvas.hidden = 1
document.body.appendChild(zcanvas);
zcanvas.style.background = 'black'
let zctx = zcanvas.getContext('2d');

let ztime = 0

class Blackscreen {
    constructor(length) {
        this.length = length + 60
        this.maxlength = this.length
    }
    draw() {
        this.length--
        if (this.length > 0) {
            canvas_context.fillStyle = 'black'
            canvas_context.fillRect(0, 0, 4000, 4000)
            canvas_context.fillStyle = 'white'
            canvas_context.font = "40px comic sans ms"

            ztime += .01
            let pz = zctx.getImageData(0, 0, 256, 256)

            let dz = pz.data
            for (let t = 0; t < dz.length; t += 4) {
                dz[t] = Math.cos(ztime / 10) * 255
                dz[t + 1] = Math.cos((((t / 4) % 256) / 6) * ztime) * 255
                dz[t + 2] = (Math.random() * 255) * Math.sin(ztime)
                dz[t + 3] = 0 //this is the shader opacity 255 is max 0 is none
            }
            zctx.putImageData(pz, 0, 0)
            canvas_context.drawImage(zcanvas, 0, 0, zcanvas.width, zcanvas.height, 0, 0, canvas.width, canvas.height)

            let transform = canvas_context.getTransform();
            if (this.length < (this.maxlength / 4) * 1) {
                canvas_context.fillText('Loading...', (canvas.width / 2) - transform.e, canvas.height / 2)
            } else if (this.length < (this.maxlength / 4) * 2) {
                canvas_context.fillText('Loading..', (canvas.width / 2) - transform.e, canvas.height / 2)
            } else if (this.length < (this.maxlength / 4) * 3) {
                canvas_context.fillText('Loading.', (canvas.width / 2) - transform.e, canvas.height / 2)
            } else {
                canvas_context.fillText('Loading', (canvas.width / 2) - transform.e, canvas.height / 2)
            }


        }
    }
}
