class BlurHolder {
    constructor(h) {
        this.blurs = []
        let epr = {}
        epr.r = 128
        epr.g = 128
        epr.b = 128
        this.hort = epr
        for (let t = 0; t < h; t++) {
            let pr = {}
            pr.r = 128
            pr.g = 128
            pr.b = 128
            this.blurs.push(pr)
        }
    }
}

let bholder = new BlurHolder(1920)

function indexToPoint(index, width) {
    let y = Math.floor(index / (4 * width));
    let x = (index / 4) % width;
    return { x, y };
}



let xpoint = 0
let ypoint = 0
let xscaler = 0
let yscaler = 0

function canvasScale() {

    x = win.innerWidth || docElem.clientWidth || body.clientWidth
    y = win.innerHeight || docElem.clientHeight || body.clientHeight

    xrat = x / 1920
    yrat = y / 1080

    // realcanvas_context.globalAlpha = 1
    if (blure == 1) {
        realcanvas.width = window.innerWidth;
        realcanvas.height = window.innerHeight;

        realcanvas_context.ImageSmoothingEnabled = false
        realcanvas_context.drawImage(canvas, 0, 0, canvas.width, canvas.height, 0, 0, realcanvas.width * .025, realcanvas.height * .025)
        // bholder = new BlurHolder(Math.ceil(realcanvas.width*.025))


        if (blurstack == 0) {
            pixg = realcanvas_context.getImageData(0, 0, realcanvas.width * .025, realcanvas.height * .025);
            blurstack = 1;
            let pl = pixg.data;
            let rat = .5

            for (let t = 0; t < pl.length; t += 4) {
                let p = indexToPoint(t, Math.floor(realcanvas.width * .025));

                if (!bholder.blurs[p.x]) {
                    bholder.blurs[p.x] = { r: 0, g: 0, b: 0 };
                }

                bholder.blurs[p.x].r = (bholder.blurs[p.x].r + pl[t] * rat) / (1 + rat);
                bholder.blurs[p.x].g = (bholder.blurs[p.x].g + pl[t + 1] * rat) / (1 + rat);
                bholder.blurs[p.x].b = (bholder.blurs[p.x].b + pl[t + 2] * rat) / (1 + rat);

                bholder.hort.r = (bholder.hort.r + pl[t] * rat) / (1 + rat);
                bholder.hort.g = (bholder.hort.g + pl[t + 1] * rat) / (1 + rat);
                bholder.hort.b = (bholder.hort.b + pl[t + 2] * rat) / (1 + rat);


                for (let f = Math.max(0, p.x - 10); f < Math.min(Math.floor(realcanvas.width * .025), p.x + 10); f++) {

                    bholder.blurs[p.x].r += bholder.blurs[f].r * .025
                    bholder.blurs[p.x].r /= 1.025
                    bholder.blurs[p.x].b += bholder.blurs[f].b * .025
                    bholder.blurs[p.x].b /= 1.025
                    bholder.blurs[p.x].g += bholder.blurs[f].g * .025
                    bholder.blurs[p.x].g /= 1.025
                }





                pl[t] = (bholder.hort.r + bholder.blurs[p.x].r) / 2;
                pl[t + 1] = (bholder.hort.g + bholder.blurs[p.x].g) / 2;
                pl[t + 2] = (bholder.hort.b + bholder.blurs[p.x].b) / 2;
                pl[t + 3] = 255; // Full opacity
            }

            // console.log("hi");
        }

        // console.log(pixg);
        // realcanvas_context.ImageSmoothingEnabled = false
        // realcanvas_context.putImageData(pixg, 0, 0);
        realcanvas_context.drawImage(realcanvas, 0, 0, realcanvas.width * .025, realcanvas.height * .025, 0, 0, realcanvas.width, realcanvas.height)
        realcanvas_context.drawImage(realcanvas, 0, 0, realcanvas.width, realcanvas.height, 0, 0, realcanvas.width * .025, realcanvas.height * .025)
        realcanvas_context.drawImage(realcanvas, 0, 0, realcanvas.width * .025, realcanvas.height * .025, 0, 0, realcanvas.width, realcanvas.height)

        realcanvas_context.font = "550px comic sans ms"
        realcanvas_context.fillStyle = "white"
        realcanvas_context.fillText("dummy text for display", 500, 500)

    } else {

        realcanvas.width = window.innerWidth;
        realcanvas.height = window.innerHeight;




        if (realcanvas.height / realcanvas.width >= ninth) {
            realcanvas_context.drawImage(canvas, 0, 0, canvas.width, canvas.height, 0, (realcanvas.height - (ninth * realcanvas.width)) / 2, realcanvas.width, ninth * realcanvas.width)

            xpoint = 0
            ypoint = (realcanvas.height - (ninth * realcanvas.width)) / 2
            canvasSuperDisp = ypoint
            canvasSuperDispx = 0
            xscaler = Math.min(realcanvas.width / 1920, realcanvas.height / 1080)
        } else {
            realcanvas_context.drawImage(canvas, 0, 0, canvas.width, canvas.height, (realcanvas.width - (realcanvas.height / ninth)) / 2, 0, realcanvas.height / ninth, realcanvas.height)

            xpoint = (realcanvas.width - (realcanvas.height / ninth)) / 2
            xscaler = Math.min(realcanvas.width / 1920, realcanvas.height / 1080)
            ypoint = 0
            canvasSuperDisp = 0
            canvasSuperDispx = xpoint
        }



        dekoshift.draw()

    }




    // // if(blure == 1){
    //     realcanvas_context.globalAlpha = 1
    // }
    // var win = window
    // let doc = document
    // let docElem = doc.documentElement
    // let body = doc.getElementsByTagName('body')[0]

    // let x = win.innerWidth || docElem.clientWidth || body.clientWidth
    // let y = win.innerHeight || docElem.clientHeight || body.clientHeight

    //  xrat = x / 1920
    //  yrat = y / 1080


    // secretCanvas.width = 1920 //why does this work????
    // secretCanvas.height = 1080
    // secretCanvasContext.clearRect(0, 0, 1920, 1080)
    // secretCanvasContext.drawImage(canvas, 0, 0)
    // canvas.width = window.innerWidth; 
    // canvas.height = window.innerHeight;


    // canvas_context.drawImage(secretCanvas, 0, 0, 1920, 1080, 0, 0, window.innerWidth, window.innerHeight)
}


