class Bookinventory {
    constructor(inv, sel = 0) {
        this.sel = sel
        this.inventory = inv
    }
    draw() {
        backManager.lockflag = 1
        let scaler = 40
        this.drawer = []
        if (throttleStickToScrollRate(keysPressed['w'], globalThrottle)) {
            keysPressed['w'] = false
            this.sel--
            if (this.sel < 0) {
                this.sel = 0
            }
        }
        if (throttleStickToScrollRate(keysPressed['s'], globalThrottle)){
            keysPressed['s'] = false
            this.sel++
            if (this.sel > this.inventory.length - 1) {
                this.sel = this.inventory.length - 1
            }
        }
        if (keysPressed[' ']) {
            deko.sel1 = this.sel
            cleanupGift(deko.givtforms[deko.giveTo.parent.id])
            //for 237 this should be deko.givtforms[237] = [0,1,2,3,4,5...60]
        }
        for (let t = Math.max(this.sel - 3, 0); t < Math.min(this.inventory.length, this.sel + 3); t++) {
            console.log(this.sel, t)
            if (t == this.sel) {

                let bookrect = new Rectangle(backManager.offset.x, (1080 / 2) + ((t - this.sel) * (scaler * 1.5)), 400, scaler, "#FFFFFF80") //deko you can make this any color for the menu backrgroudn 
                bookrect.id = this.inventory[t].id
                this.drawer.push(bookrect)
            } else {

                let bookrect = new Rectangle(backManager.offset.x, (1080 / 2) + ((t - this.sel) * (scaler * 1.5)), 400, scaler, "#44444440")
                bookrect.id = this.inventory[t].id
                this.drawer.push(bookrect)
            }
        }
        canvas_context.fillStyle = "gold"
        canvas_context.strokeStyle = "black"
        for (let t = 0; t < this.drawer.length; t++) {
            this.drawer[t].draw()

            canvas_context.fillStyle = "gold"
            canvas_context.strokeStyle = "black"
            canvas_context.font = `${scaler * .9}px comic sans ms`
            canvas_context.drawImage(itemSprites[this.drawer[t].id], 0, 0, itemSprites[this.inventory[t].id].width, itemSprites[this.inventory[t].id].height, this.drawer[t].x, this.drawer[t].y, scaler, scaler) //this would change the bubble
            canvas_context.strokeText(backupNames[this.drawer[t].id + 1], this.drawer[t].x + 50, this.drawer[t].y + (scaler * .9), 350)
            canvas_context.fillText(backupNames[this.drawer[t].id + 1], this.drawer[t].x + 50, this.drawer[t].y + (scaler * .9), 350)

        }
    }
}
