let destroyTimers = []
function ManageDestroyTimers() {
    for (let t = 0; t < destroyTimers.length; t++) {
        destroyTimers[t].time--
        if (destroyTimers[t].time == 1) {
            eval(destroyTimers[t].trigger)
            playedTriggers.push(destroyTimers[t].trigger)
            destroyTimers.splice(t, 1)
            t--
        }
    }
}
