function seark(joesma, sy) {
    joesma++
    let shoebox = []
    for (let t = 0; t < dialogueList.length; t++) {
        if (dialogueList[t].hasHad == 1) {
            let spark = (dialogueList[t].ChatID).split(',')

            if (joesma == spark[1]) {
                // console.log(joesma, spark)
                shoebox.push(fullFaceFix(spark[0]))
            }
        }
    }
    let fakeout = new ReckonedFaces(shoebox, joesma)
    fakeout.phonePass = joesma
    fakeout.y = sy
    return fakeout
}



