class ReckonedFaces {
    constructor(whomstdve, num) {
        this.huh = whomstdve
        this.who = num

    }
    draw() {
        // console.log(this)


        if (notalkers.includes(this.who)) {

            return
        }


        for (let m = 0; m < backManager.people[backManager.slide].length; m++) {
            if (this.who == backManager.people[backManager.slide][m].form + 1) {
                this.whois = m
            }
        }

        let scale = 48
        let transform = canvas_context.getTransform();
        let x = backManager.people[backManager.slide][this.whois].body.x + 266 //these constants, 256 and 512 are things keyscan p-scan p scan scanp //remember to use  backManager.people[backManager.slide][this.whois].scale thi sis the person's size, use this as a multiplier // black box // blackbox
        let y = backManager.people[backManager.slide][this.whois].body.y - 512


        if (lefties[backManager.people[backManager.slide][this.whois].form] == 1) {
            x -= 712
        }

        if (xoffst[backManager.people[backManager.slide][this.whois].form] >= -999999999) {
            x += xoffst[backManager.people[backManager.slide][this.whois].form]
        }
        if (yoffst[backManager.people[backManager.slide][this.whois].form] >= -999999999) {
            y += yoffst[backManager.people[backManager.slide][this.whois].form]
        }







        let rectout = new Rectangle(x - 24, y - 24, (7 * 48) + 24, (11 * 48) + 24, "#00000088")
        rectout.draw()
        for (let t = 0; t < 7; t++) {
            for (let k = 0; k < 11; k++) {
                let faceIndex = (t * 11 + k)

                for (let m = 0; m < backManager.people[backManager.slide].length; m++) {
                    if (this.who == backManager.people[backManager.slide][m].form + 1) {
                        this.whois = m
                    }
                }

                let scale = 48
                let transform = canvas_context.getTransform();
                x = backManager.people[backManager.slide][this.whois].body.x + 256 //these constants, 256 and 512 are things keyscan p-scan p scan scanp //remember to use  backManager.people[backManager.slide][this.whois].scale thi sis the person's size, use this as a multiplier
                y = backManager.people[backManager.slide][this.whois].body.y - 512

                if (lefties[backManager.people[backManager.slide][this.whois].form] == 1) {
                    x -= 712
                }

                if (xoffst[backManager.people[backManager.slide][this.whois].form] >= -999999999) {
                    x += xoffst[backManager.people[backManager.slide][this.whois].form]
                }
                if (yoffst[backManager.people[backManager.slide][this.whois].form] >= -999999999) {
                    y += yoffst[backManager.people[backManager.slide][this.whois].form]
                }

                // if(Math.sign(backManager.people[backManager.slide][this.whois].body.x-(backManager.slides[backManager.slide].width/2)) == 1){
                //     x-=(scale*7)
                // }
                // x-=transform.e
                x += (t * scale)
                y += (k * scale)


                if (this.who == 156) {
                    console.log(faceIndex, backManager.people[backManager.slide][this.whois].charactersRung)

                    let f = 0
                    for (let g = 0; g < backManager.people[backManager.slide][this.whois].charactersRung.length; g++) {
                        if (backManager.people[backManager.slide][this.whois].charactersRung[g][0] - 1 == faceIndex) {
                            f = 1
                        }
                    }

                    if (f == 1) {
                        canvas_context.drawImage(faceArray[faceIndex][0], 0, 0, faceArray[faceIndex][0].width, faceArray[faceIndex][0].height, x, y, scale, scale)
                    }
                } else {

                    if (this.huh.includes(faceArray[faceIndex][1] + 1)) {
                        canvas_context.drawImage(faceArray[faceIndex][0], 0, 0, faceArray[faceIndex][0].width, faceArray[faceIndex][0].height, x, y, scale, scale)
                    }
                }

            }
        }

    }

}





