class ElevatorMenu {
    constructor(x, y) {
        this.posx = x
        this.posy = y
        this.sel = 0
        this.images = elevs
        this.active = 0
    }
    thingIcantexplaind() {

        if (this.active == 1) {
            if (keysPressed['8']) {
                this.sel = 8
            }
            if (keysPressed['7']) {
                this.sel = 7
            }
            if (keysPressed['6']) {
                this.sel = 6
            }
            if (keysPressed['5']) {
                this.sel = 5
            }
            if (keysPressed['4']) {
                this.sel = 4
            }
            if (keysPressed['3']) {
                this.sel = 3
            }
            if (keysPressed['2']) {
                this.sel = 2
            }
            if (keysPressed['1']) {
                this.sel = 1
            }
            if (keysPressed['0']) {
                this.sel = 0
            }

            if (throttleStickToScrollRate(keysPressed['w'], globalThrottle)) {
                keysPressed['w'] = false
                if (this.sel < 7) {
                    this.sel += 2
                } else {
                    this.sel = 8
                }
            }
            if (throttleStickToScrollRate(keysPressed['s'], globalThrottle)) {
                keysPressed['s'] = false
                if (this.sel > 1) {
                    this.sel -= 2
                } else {
                    this.sel = 0
                }
            }
            if (throttleStickToScrollRate(keysPressed['a'], globalThrottle)) {
                keysPressed['a'] = false
                if (this.sel > 0) {
                    this.sel -= 1
                }
            }
            if (throttleStickToScrollRate(keysPressed['d'], globalThrottle)) {
                keysPressed['d'] = false
                if (this.sel < 8) {
                    this.sel += 1
                }
            }

            if (keysPressed[" "]) {
                let ratioExplicit = dust[87 + (this.sel - 1 + 1)].height / 1080
                if (this.sel - 1 == -1) {
                    backManager.offset.x = 1050 / ratioExplicit
                    backManager.offset.y = 776 / ratioExplicit
                    gradOut(backManager.music[backManager.slide], backManager.music[87 + (this.sel - 1 + 1)])
                    backManager.slide = 87 + (this.sel - 1 + 1)
                    backManager.hot = 1
                } else if (this.sel - 1 == 7) {
                    backManager.offset.x = 2040
                    backManager.offset.y = 860
                    gradOut(backManager.music[backManager.slide], backManager.music[88 + (this.sel - 1 + 1)])
                    backManager.slide = 88 + (this.sel - 1 + 1)
                    backManager.hot = 1
                } else {
                    backManager.offset.x = 1624 / ratioExplicit
                    backManager.offset.y = 710 / ratioExplicit

                    gradOut(backManager.music[backManager.slide], backManager.music[87 + (this.sel - 1 + 1)])
                    backManager.slide = 87 + (this.sel - 1 + 1)
                    backManager.hot = 1
                }
                emenu.active = 0
            }
        }
    }
    draw() {
        //get transform? or anchor to something?
        // this.posx = backManager.offset.x - 200
        // this.posy = backManager.offset.y - 600
        if (this.active == 1) {
            backManager.lock = 1
            backManager.locktimer = 10

            canvas_context.drawImage(this.images[this.sel], 0, 0, this.images[this.sel].width, this.images[this.sel].height, this.posx, this.posy, this.images[this.sel].width / 1.4, this.images[this.sel].height / 1.4)


        }
    }
    check(point) {
        if (this.active == 1) {
            for (let t = -1; t < 8; t++) {
                let p1 = new Circle(105 + (Math.max((t) % 2, 0) * (180 / 1.4)) + this.posx, (676 / 1.4) - (Math.floor((t) / 2) * (180 / 1.4)) + this.posy, 50, "WHite")
                if (t == -1) {
                    p1.x += 180 / 1.4
                }
                if (p1.isPointInside(point)) {
                    let ratioExplicit = dust[87 + (t + 1)].height / 1080
                    if (t == -1) {
                        backManager.offset.x = 1050 / ratioExplicit
                        backManager.offset.y = 776 / ratioExplicit
                        gradOut(backManager.music[backManager.slide], backManager.music[87 + (t + 1)])
                        backManager.slide = 87 + (t + 1)
                        backManager.hot = 1
                    } else if (t == 7) {
                        backManager.offset.x = 2040
                        backManager.offset.y = 860
                        gradOut(backManager.music[backManager.slide], backManager.music[88 + (t + 1)])
                        backManager.slide = 88 + (t + 1)
                        backManager.hot = 1
                    } else {
                        backManager.offset.x = 1624 / ratioExplicit
                        backManager.offset.y = 710 / ratioExplicit

                        gradOut(backManager.music[backManager.slide], backManager.music[87 + (t + 1)])
                        backManager.slide = 87 + (t + 1)
                        backManager.hot = 1
                    }
                    emenu.active = 0
                }
            }
        }
    }
}



