let scriptText = "{}"
let saveNewLatch = 0


if (window.electron) {

    window.electron.getUserDataPath()
        .then((userDataPath) => {
            // saveNewLatch = 1


            console.log(userDataPath, userDataPath + `/Deko Save.js`)
            var script = document.createElement("script");
            script.setAttribute("type", "text/javascript");
            script.setAttribute("src", userDataPath + `/Deko Save.js`);
            document.getElementsByTagName("head")[0].appendChild(script)
            scriptText = script
        })
        .catch((error) => {
            console.error('Error fetching userData path:', error);
        });
}

function DestroyAndScript(item) {
    let scri = `for(let z = 0;z<itemList.length;z++){if(itemList[z].id==${item}){itemList[z].x = 99999999}}`
    eval(scri)
    playedTriggers.push(scri)
}


function DestroyYeetRoom(item) {
    for (let z = 0; z < itemList.length; z++) { if (itemList[z].id == item) { itemList[z].room = 99999999 } }
}

function Destroy(item) {
    for (let z = 0; z < itemList.length; z++) { if (itemList[z].id == item) { itemList[z].x = 99999999 } }
}



function ChangeItemCharacteristic(item, characteristic) {
    for (let z = 0; z < itemList.length; z++) { if (itemList[z].id == item) { itemList[z].characteristic = characteristic } }
}

let storedDestroyedCrap = []
function DestroyInventoryItem(item) {
    for (let z = 0; z < deko.inventory.length; z++) { if (deko.inventory[z].id == item) { delete deko.inventory[z].menu; storedDestroyedCrap.push(deko.inventory[z]); deko.inventory.splice(z, 1) } }
}


