let cdholder = 0
function shiftCD() {
    console.log("r")
    for (let z = 0; z < itemList.length; z++) {
        if (itemList[z].room == 113) { // z is overworld dreams    // w is also overworld(?)
            if (itemList[z].id == 52) {
                console.log("r")
                continue
            } else {
                console.log("r")
                if (itemList[z].y > 0) {
                    console.log("r")
                    for (let w = 0; w < itemList.length; w++) {
                        if (itemList[w].room == 113) {
                            console.log("r")
                            if (itemList[w].id == 52) {
                                console.log("r")
                                console.log(dreamID[cdID.indexOf(deko.cdPlayerItemNumber)], deko.cdPlayerItemNumber, w)
                                continue
                            } else if (w + 1 == dreamID[cdID.indexOf(deko.cdPlayerItemNumber)]) {
                                console.log("r")
                                // if(itemList[w].y < 0){
                                console.log("r")
                                cdholder++
                                // Swap y-values
                                let tempY = itemList[w].y;
                                itemList[w].y = itemList[z].y;
                                itemList[z].y = tempY;

                                // Swap x-values
                                let tempX = itemList[w].x;
                                itemList[w].x = itemList[z].x;
                                itemList[z].x = tempX;
                                cdholder %= 5
                                // }else{
                                //     cdholder%= 5
                                //     cdholder++
                                // }
                                console.log(dreamID[cdID.indexOf(deko.cdPlayerItemNumber)], deko.cdPlayerItemNumber, w)
                            } else {
                                console.log(dreamID[cdID.indexOf(deko.cdPlayerItemNumber)], deko.cdPlayerItemNumber, w)
                                cdholder %= 5
                                cdholder++
                            }
                        }
                    }
                }
            }
        }
    }
}


